<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { api, getErrorMessage } from '../core/api'

type GroupRow={id:number;name:string;platform:string;status:string}
type Channel={id:number;name:string;description?:string;status:string;billing_model_source?:string;restrict_models?:boolean;group_ids?:number[];model_mapping?:Record<string,Record<string,string>>;model_pricing?:Array<{platform:string;models:string[];billing_mode:string;input_price?:number|null;output_price?:number|null}>;updated_at?:string}
type ListResponse<T>={items?:T[];total?:number}
const loading=ref(false), error=ref(''), notice=ref(''), search=ref(''), status=ref('')
const channels=ref<Channel[]>([]), groups=ref<GroupRow[]>([])
const showEditor=ref(false), editingId=ref<number|null>(null), busy=ref(false)
const form=reactive({name:'',description:'',status:'active',billing_model_source:'requested',restrict_models:true,group_ids:[] as number[],platform:'openai',models:''})

const filtered=computed(()=>{const q=search.value.trim().toLowerCase();return channels.value.filter(c=>(!status.value||c.status===status.value)&&(!q||`${c.name} ${c.description||''} ${c.id} ${groupNames(c)}`.toLowerCase().includes(q)))})
const activeCount=computed(()=>channels.value.filter(c=>c.status==='active').length)
const modelCount=computed(()=>channels.value.reduce((n,c)=>n+mappingModels(c).length,0))
const groupCount=computed(()=>new Set(channels.value.flatMap(c=>c.group_ids||[])).size)
function groupNames(c:Channel){return (c.group_ids||[]).map(id=>groups.value.find(g=>g.id===id)?.name||`#${id}`).join(' · ')||'未绑定'}
function mappingModels(c:Channel){const s=new Set<string>();Object.values(c.model_mapping||{}).forEach(m=>Object.keys(m||{}).forEach(x=>s.add(x)));return [...s].sort()}
function pricingCount(c:Channel){return (c.model_pricing||[]).reduce((n,p)=>n+(p.models?.length||0),0)}
function platformLabel(p:string){return ({openai:'OpenAI Compatible',anthropic:'Anthropic',gemini:'Gemini',antigravity:'Antigravity',grok:'xAI / Grok'} as Record<string,string>)[p]||p}
async function load(){loading.value=true;error.value='';try{const [cr,gr]=await Promise.all([api.get<ListResponse<Channel>>('/admin/channels',{params:{page:1,page_size:200,sort_by:'created_at',sort_order:'desc'}}),api.get<GroupRow[]>('/admin/groups/all',{params:{include_inactive:true}})]);channels.value=Array.isArray(cr.data?.items)?cr.data.items:[];groups.value=Array.isArray(gr.data)?gr.data:[]}catch(e){error.value=getErrorMessage(e)}finally{loading.value=false}}
function openCreate(){editingId.value=null;Object.assign(form,{name:'',description:'',status:'active',billing_model_source:'requested',restrict_models:true,group_ids:[],platform:'openai',models:''});showEditor.value=true}
function openEdit(c:Channel){editingId.value=c.id;const platforms=Object.keys(c.model_mapping||{});Object.assign(form,{name:c.name,description:c.description||'',status:c.status||'active',billing_model_source:c.billing_model_source||'requested',restrict_models:c.restrict_models!==false,group_ids:[...(c.group_ids||[])],platform:platforms[0]||groups.value.find(g=>c.group_ids?.includes(g.id))?.platform||'openai',models:mappingModels(c).join('\n')});showEditor.value=true}
function parseModels(){return [...new Set(form.models.split(/[\n,]+/).map(x=>x.trim()).filter(Boolean))].sort()}
async function save(){if(!form.name.trim())return;busy.value=true;error.value='';try{const models=parseModels();const base={name:form.name.trim(),description:form.description.trim(),group_ids:form.group_ids,billing_model_source:form.billing_model_source,restrict_models:form.restrict_models,features:'',features_config:{},apply_pricing_to_account_stats:false};if(editingId.value){const existing=channels.value.find(c=>c.id===editingId.value);const payload:any={...base,status:form.status};if(models.length){payload.model_mapping={...(existing?.model_mapping||{}),[form.platform]:Object.fromEntries(models.map(m=>[m,m]))}}await api.put(`/admin/channels/${editingId.value}`,payload)}else{if(!models.length)throw new Error('新建渠道至少填写一个模型');await api.post('/admin/channels',{...base,model_mapping:{[form.platform]:Object.fromEntries(models.map(m=>[m,m]))},model_pricing:[]})}showEditor.value=false;notice.value=editingId.value?'渠道已更新':'渠道已创建';await load()}catch(e){error.value=getErrorMessage(e)}finally{busy.value=false}}
async function toggle(c:Channel){try{await api.put(`/admin/channels/${c.id}`,{status:c.status==='active'?'disabled':'active'});await load()}catch(e){error.value=getErrorMessage(e)}}
onMounted(()=>void load())
</script>

<template><section class="channels-page"><header class="head"><div><span>ROUTING &amp; CATALOG</span><h1>渠道与价格</h1><p>真实 Channel 配置。这里的模型映射与分组绑定会直接进入模型广场与渠道定价链路。</p></div><div><button class="ghost" @click="load">{{loading?'刷新中':'刷新'}}</button><button class="primary" @click="openCreate">＋ 新增渠道</button></div></header>
<section class="stats"><article><span>渠道总数</span><strong>{{channels.length}}</strong><small>{{activeCount}} 个启用</small></article><article><span>目录模型</span><strong>{{modelCount}}</strong><small>真实 model_mapping</small></article><article><span>关联分组</span><strong>{{groupCount}}</strong><small>参与路由/展示</small></article><article><span>显式定价</span><strong>{{channels.reduce((n,c)=>n+pricingCount(c),0)}}</strong><small>未配置时使用官方参考价</small></article></section>
<p v-if="error" class="alert bad">{{error}}</p><p v-if="notice" class="alert good">{{notice}}</p>
<section class="panel"><header class="toolbar"><div><strong>渠道配置</strong><span>{{filtered.length}} / {{channels.length}}</span></div><div><input v-model="search" placeholder="搜索渠道、分组或 ID"/><select v-model="status"><option value="">全部状态</option><option value="active">启用</option><option value="disabled">停用</option></select></div></header>
<div class="table"><div class="thead"><span>渠道</span><span>状态</span><span>分组</span><span>模型</span><span>定价</span><span>计费模型</span><span></span></div><div v-for="c in filtered" :key="c.id" class="row"><span class="identity"><i>C</i><span><b>{{c.name}}</b><small>#{{c.id}} · {{c.description||'暂无说明'}}</small></span></span><span><em class="state" :class="c.status"><i></i>{{c.status==='active'?'启用':'停用'}}</em></span><span class="groups">{{groupNames(c)}}</span><span><b>{{mappingModels(c).length}}</b><small class="stack"> 个映射</small></span><span><b>{{pricingCount(c)}}</b><small class="stack"> 个显式价</small></span><span><code>{{c.billing_model_source||'requested'}}</code></span><span class="actions"><button @click="toggle(c)">{{c.status==='active'?'暂停':'启用'}}</button><button @click="openEdit(c)">编辑</button></span></div><div v-if="!filtered.length&&!loading" class="empty">暂无真实渠道。可在“分组与模型”同步发布，也可在这里手动创建。</div></div></section>
<div v-if="showEditor" class="overlay" @click.self="showEditor=false"><form class="dialog" @submit.prevent="save"><header><div><span>CHANNEL CONFIGURATION</span><h2>{{editingId?'编辑渠道':'新增渠道'}}</h2></div><button type="button" @click="showEditor=false">×</button></header><div class="form"><label class="wide"><span>渠道名称</span><input v-model="form.name" required/></label><label><span>模型协议</span><select v-model="form.platform"><option value="openai">OpenAI Compatible</option><option value="anthropic">Anthropic</option><option value="gemini">Gemini</option><option value="antigravity">Antigravity</option><option value="grok">xAI / Grok</option></select></label><label><span>计费模型来源</span><select v-model="form.billing_model_source"><option value="requested">请求模型</option><option value="upstream">上游模型</option><option value="channel_mapped">渠道映射模型</option></select></label><label v-if="editingId"><span>状态</span><select v-model="form.status"><option value="active">启用</option><option value="disabled">停用</option></select></label><label class="wide"><span>关联分组</span><div class="checks"><label v-for="g in groups" :key="g.id"><input v-model="form.group_ids" type="checkbox" :value="g.id"/><span>{{g.name}} · {{platformLabel(g.platform)}}</span></label></div></label><label class="wide"><span>模型映射（每行一个，默认一一映射）</span><textarea v-model="form.models" rows="7" placeholder="gpt-5\nclaude-sonnet-4-6\ngemini-..."/></label><label class="wide inline"><input v-model="form.restrict_models" type="checkbox"/><span>限制为上述模型映射</span></label><label class="wide"><span>说明</span><textarea v-model="form.description" rows="3"/></label></div><footer><button type="button" class="ghost" @click="showEditor=false">取消</button><button class="primary" :disabled="busy">{{busy?'保存中…':'保存渠道'}}</button></footer></form></div>
</section></template>

<style scoped>.channels-page{--border:#252a31;--border2:#353b44;--text:#f4f6f8;color:var(--text);width:100%;font-size:14px}.head{display:flex;justify-content:space-between;gap:24px;padding:2px 0 24px}.head>div:first-child>span,.dialog header span{color:#65707c;font-size:.65rem;font-weight:700;letter-spacing:.12em}.head h1{margin:8px 0 0;font-size:2.05rem;line-height:1;font-weight:700;letter-spacing:-.045em}.head p{margin:11px 0 0;color:#838d98;font-size:.84rem}.head>div:last-child{display:flex;gap:8px}.ghost,.primary{height:40px;padding:0 14px;border:1px solid var(--border2);border-radius:8px;background:#13161b;color:#cbd1d7;cursor:pointer}.primary{border-color:#e0e4e8;background:#f1f3f5;color:#111318;font-weight:680}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--border);border-radius:12px;background:#101217;overflow:hidden}.stats article{min-height:110px;padding:20px;position:relative;display:flex;flex-direction:column;justify-content:center}.stats article+article:before{content:"";position:absolute;left:0;top:20px;bottom:20px;width:1px;background:#282d34}.stats span{color:#7a848f;font-size:.68rem}.stats strong{margin-top:8px;font-size:1.75rem}.stats small{margin-top:7px;color:#626c77;font-size:.63rem}.alert{margin:12px 0 0;padding:10px 12px;border-radius:8px;font-size:.7rem}.alert.bad{border:1px solid rgba(225,108,115,.28);background:rgba(225,108,115,.06);color:#e4a0a5}.alert.good{border:1px solid rgba(67,205,152,.22);background:rgba(67,205,152,.05);color:#8dd7b9}.panel{margin-top:14px;border:1px solid var(--border);border-radius:12px;background:#0f1115;overflow:hidden}.toolbar{min-height:68px;padding:12px 14px 12px 18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border)}.toolbar>div{display:flex;align-items:center;gap:8px}.toolbar span{color:#65707b;font-size:.65rem}.toolbar input,.toolbar select,.form input,.form select,.form textarea{border:1px solid #2d323a;border-radius:8px;background:#0b0d11;color:#e8ebee;outline:none}.toolbar input{width:270px;height:40px;padding:0 11px}.toolbar select{height:40px;padding:0 10px}.thead,.row{display:grid;grid-template-columns:minmax(250px,1.45fr) 90px minmax(170px,1fr) 80px 90px 120px 130px;gap:14px;align-items:center}.thead{min-height:42px;padding:0 18px;border-bottom:1px solid #22272e;color:#68727d;font-size:.62rem}.row{min-height:70px;padding:0 18px;border-bottom:1px solid #1f2329}.row:last-child{border-bottom:0}.identity{display:flex;align-items:center;gap:10px;min-width:0}.identity>i{width:34px;height:34px;border:1px solid #333942;border-radius:9px;background:#171a1f;display:grid;place-items:center;font-style:normal;font-weight:700}.identity>span{min-width:0;display:flex;flex-direction:column}.identity b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.74rem}.identity small{margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#68727d;font-size:.61rem}.state{display:inline-flex;align-items:center;gap:6px;font-style:normal;color:#b7bec6;font-size:.65rem}.state i{width:6px;height:6px;border-radius:50%;background:#7b848e}.state.active{color:#8ed8ba}.state.active i{background:#43cd98}.groups{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#a9b1b9;font-size:.67rem}.stack{display:block;margin-top:4px;color:#68727d;font-size:.59rem}.row code{color:#98abc0;font-size:.63rem}.actions{display:flex;gap:5px}.actions button{height:30px;padding:0 8px;border:1px solid #303640;border-radius:6px;background:#14171c;color:#aeb6be;font-size:.61rem}.empty{min-height:240px;display:grid;place-items:center;color:#68727d}.overlay{position:fixed;inset:0;z-index:80;padding:22px;background:rgba(0,0,0,.7);backdrop-filter:blur(8px);display:grid;place-items:center}.dialog{width:min(690px,100%);max-height:90vh;overflow:auto;border:1px solid #343a43;border-radius:14px;background:#111318}.dialog>header{padding:19px 21px;display:flex;justify-content:space-between;border-bottom:1px solid #262b32}.dialog h2{margin:6px 0 0;font-size:1.2rem}.dialog>header button{width:34px;height:34px;border:1px solid #303640;border-radius:8px;background:#171a1f;color:#a2abb5}.form{padding:20px 21px;display:grid;grid-template-columns:1fr 1fr;gap:14px}.form>label{display:flex;flex-direction:column;gap:7px}.form>label.wide{grid-column:1/-1}.form>label>span{color:#7d8792;font-size:.67rem}.form input,.form select{height:40px;padding:0 10px}.form textarea{padding:10px;resize:vertical}.checks{max-height:150px;padding:8px;border:1px solid #292e36;border-radius:8px;background:#0b0d11;display:grid;grid-template-columns:1fr 1fr;gap:4px}.checks label{min-height:32px;padding:0 7px;border-radius:6px;display:flex;align-items:center;gap:8px;color:#b8c0c8;font-size:.65rem}.checks label:hover{background:#14181e}.checks input{height:auto}.form .inline{flex-direction:row;align-items:center}.form .inline input{height:auto}.dialog footer{padding:14px 21px;border-top:1px solid #262b32;display:flex;justify-content:flex-end;gap:8px}@media(max-width:1050px){.thead,.row{grid-template-columns:minmax(230px,1.5fr) 85px minmax(150px,1fr) 70px 110px}.thead>span:nth-child(5),.row>span:nth-child(5),.thead>span:nth-child(6),.row>span:nth-child(6){display:none}}@media(max-width:720px){.head{flex-direction:column}.head>div:last-child{width:100%}.head button{flex:1}.stats{grid-template-columns:1fr 1fr}.stats article:nth-child(3):before{display:none}.stats article:nth-child(n+3){border-top:1px solid #282d34}.toolbar{align-items:flex-start;flex-direction:column;gap:9px}.toolbar>div:last-child{width:100%}.toolbar input{width:100%;flex:1}.thead{display:none}.row{grid-template-columns:1fr auto;min-height:76px}.row>span:not(.identity):not(.actions){display:none}.form{grid-template-columns:1fr}.form>label.wide{grid-column:auto}.checks{grid-template-columns:1fr}}</style>